# Subconverter 自动部署脚本 (Windows PowerShell) $ErrorActionPreference = "Stop" Write-Host "=== Subconverter 自动部署脚本 ===" -ForegroundColor Cyan Write-Host "时间: $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')" # 配置 $IMAGE_NAME = "${env:DOCKER_IMAGE:-whua898/subconverter}" $CONTAINER_NAME = "${env:CONTAINER_NAME:-subconverter}" $HOST_PORT = "${env:HOST_PORT:-8080}" $CONFIG_MOUNT = "${env:CONFIG_MOUNT:-$(Join-Path $(Get-Location) Base):/base}" Write-Host "" Write-Host "[1/5] 拉取最新 Docker 镜像..." -ForegroundColor Yellow docker pull $IMAGE_NAME Write-Host "" Write-Host "[2/5] 停止并删除旧容器..." -ForegroundColor Yellow docker rm -f $CONTAINER_NAME 2>$null Write-Host "" Write-Host "[3/5] 启动新容器..." -ForegroundColor Yellow docker run -d ` --name $CONTAINER_NAME ` -p "${HOST_PORT}:80" ` -v $CONFIG_MOUNT ` --restart=unless-stopped ` $IMAGE_NAME Write-Host "" Write-Host "[4/5] 等待服务就绪（5秒）..." -ForegroundColor Yellow Start-Sleep -Seconds 5 Write-Host "" Write-Host "[5/5] 检查容器状态..." -ForegroundColor Yellow $container = docker ps --filter "name=$CONTAINER_NAME" --filter "status=running" --format "{{.ID}}" | Select-Object -First 1 if ($container) { Write-Host "✓ 容器运行正常" -ForegroundColor Green Write-Host " 容器ID: $container" Write-Host " 端口映射: ${HOST_PORT}:80" } else { Write-Host "✗ 容器启动失败，查看日志：" -ForegroundColor Red docker logs $CONTAINER_NAME --tail 20 exit 1 } Write-Host "" Write-Host "=== 部署完成 ===" -ForegroundColor Green Write-Host "服务地址: http://localhost:$HOST_PORT"